<?php require_once '../includes/auth.php';require_login();verify_csrf();$u=user();$code=$_POST['institution_code']??$u['institution_code'];if(!is_admin()&&!is_sub_officer())$code=$u['institution_code'];$s=mysqli_prepare($conn,"INSERT INTO wastigruh_inventory(institution_type,institution_code,category,item_name,total_qty,good_qty,damaged_qty,shortage_qty,remarks,updated_by) VALUES('wastigruh',?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE total_qty=VALUES(total_qty),good_qty=VALUES(good_qty),damaged_qty=VALUES(damaged_qty),shortage_qty=VALUES(shortage_qty),remarks=VALUES(remarks),updated_by=VALUES(updated_by)");mysqli_stmt_bind_param($s,'ssssiiiisi',$code,$_POST['category'],$_POST['item_name'],$_POST['total_qty'],$_POST['good_qty'],$_POST['damaged_qty'],$_POST['shortage_qty'],$_POST['remarks'],$u['id']);if(!mysqli_stmt_execute($s))exit(mysqli_error($conn));flash('success','Inventory item saved.');redirect('wastigruh_inventory.php');
